package Lec6;

public class Data_Demo_Demo_4 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		char ch = 'a';
		System.out.println((int) (ch));
		ch++;// ch = (char)(ch + 1);
		System.out.println(ch);
		int i = 8;
		i++;// i = (int) (i + 1);
		ch += 1;// ch = (char)(ch + 1);
		System.out.println(ch);
		i += 5;
		i = (int) (i + 5);
		int x = 42;
		System.out.println((char) (x));
		ch = (char) (ch + 1);
		byte b = 8;
		b = (byte) (b + 1);

	}

}
